def commands(binary_str):
    actions = ["wink", "double blink", "close your eyes", "jump"]
    # Consider only the rightmost five bits, pad with zeros on the left if needed
    s = binary_str[-5:].zfill(5)
    result = []
    # Bits from right to left: positions 0..3 correspond to the four actions
    for i in range(4):
        if s[-1 - i] == "1":
            result.append(actions[i])
    # Leftmost of the five bits is the reverse flag
    if s[0] == "1":
        result.reverse()
    return result
